import { copyFile, readFile, stat } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

type Credential = {
  access: string;
  refresh: string;
  expires: number;
  accountId?: string;
  email?: string;
  source?: string;
};

type Account = {
  id: string;
  credential: Credential;
  alias?: string;
  needsReauth?: boolean;
  addedAt?: number;
};

type AccountSet = {
  activeAccountId: string;
  accounts: Account[];
};

function requireAccountSet(value: unknown): AccountSet {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("cursor must be an object");
  }
  const candidate = value as Partial<AccountSet>;
  if (typeof candidate.activeAccountId !== "string" || !candidate.activeAccountId) {
    throw new Error("cursor.activeAccountId must be a non-empty string");
  }
  if (!Array.isArray(candidate.accounts) || candidate.accounts.length === 0) {
    throw new Error("cursor.accounts must contain at least one account");
  }
  for (const [index, account] of candidate.accounts.entries()) {
    if (!account || typeof account !== "object" || typeof account.id !== "string" || !account.id) {
      throw new Error(`cursor.accounts[${index}].id must be a non-empty string`);
    }
    const credential = account.credential;
    if (!credential || typeof credential !== "object") {
      throw new Error(`cursor.accounts[${index}].credential must be an object`);
    }
    if (typeof credential.access !== "string" || !credential.access) {
      throw new Error(`cursor.accounts[${index}].credential.access is missing`);
    }
    if (typeof credential.refresh !== "string" || !credential.refresh) {
      throw new Error(`cursor.accounts[${index}].credential.refresh is missing`);
    }
    if (typeof credential.expires !== "number" || !Number.isFinite(credential.expires)) {
      throw new Error(`cursor.accounts[${index}].credential.expires must be a finite number`);
    }
  }
  if (!candidate.accounts.some((account) => account.id === candidate.activeAccountId)) {
    throw new Error("cursor.activeAccountId does not identify an account");
  }
  return candidate as AccountSet;
}

const inputPath = process.argv[2];
if (!inputPath) throw new Error("usage: bun import-cursor-auth.ts <cursor-json>");

const openCodexHome = process.env.OPENCODEX_HOME || join(homedir(), ".opencodex");
const authPath = join(openCodexHome, "auth.json");
const packageRoot = join(
  process.env.APPDATA || join(homedir(), "AppData", "Roaming"),
  "npm",
  "node_modules",
  "@bitkyc08",
  "opencodex",
);
const storeModulePath = join(packageRoot, "src", "oauth", "store.ts");

const parsed = JSON.parse(await readFile(inputPath, "utf8")) as Record<string, unknown>;
const cursor = requireAccountSet(parsed.cursor);

await stat(authPath);
const stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
const backupPath = `${authPath}.bak-${stamp}-before-cursor-import`;
await copyFile(authPath, backupPath);

const store = await import(pathToFileURL(storeModulePath).href) as {
  replaceProviderAccountSet(provider: string, set: AccountSet): Promise<void>;
  getAccountSet(provider: string): AccountSet | null;
};

await store.replaceProviderAccountSet("cursor", cursor);
const saved = store.getAccountSet("cursor");
if (!saved || saved.activeAccountId !== cursor.activeAccountId || saved.accounts.length !== cursor.accounts.length) {
  throw new Error("post-write cursor account verification failed");
}

console.log(JSON.stringify({
  ok: true,
  authPath,
  backupPath,
  cursorAccounts: saved.accounts.length,
  activeAccountPresent: saved.accounts.some((account) => account.id === saved.activeAccountId),
}));

import hashlib
import json
import sqlite3
import sys
from pathlib import Path
from urllib.parse import unquote


def digest(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def candidate_strings(value):
    if isinstance(value, str):
        yield value
        decoded = unquote(value)
        if decoded != value:
            yield decoded
        try:
            parsed = json.loads(value)
        except Exception:
            return
        yield from candidate_strings(parsed)
    elif isinstance(value, dict):
        for item in value.values():
            yield from candidate_strings(item)
    elif isinstance(value, list):
        for item in value:
            yield from candidate_strings(item)


auth_path = Path(r"C:\Users\hzq00\.opencodex\auth.json")
db_path = Path(r"C:\Users\hzq00\AppData\Roaming\Cursor\User\globalStorage\state.vscdb")

auth = json.loads(auth_path.read_text(encoding="utf-8"))
cursor = auth["cursor"]
account = next(item for item in cursor["accounts"] if item["id"] == cursor["activeAccountId"])
credential = account["credential"]
targets = {
    "access": digest(credential["access"]),
    "refresh": digest(credential["refresh"]),
}
if credential.get("accountId"):
    targets["accountId"] = digest(str(credential["accountId"]))

uri = db_path.as_uri() + "?mode=ro"
connection = sqlite3.connect(uri, uri=True, timeout=10)
try:
    rows = connection.execute(
        """
        SELECT key, value
        FROM ItemTable
        WHERE lower(key) LIKE '%cursorauth%'
           OR lower(key) LIKE '%access_token%'
           OR lower(key) LIKE '%accesstoken%'
           OR lower(key) LIKE '%refresh_token%'
           OR lower(key) LIKE '%refreshtoken%'
           OR lower(key) LIKE '%membership%'
           OR lower(key) LIKE '%usagebased%'
        ORDER BY key
        LIMIT 500
        """
    ).fetchall()
finally:
    connection.close()

results = []
aggregate = {name: False for name in targets}
for key, raw_value in rows:
    if isinstance(raw_value, bytes):
        value_text = raw_value.decode("utf-8", errors="replace")
    else:
        value_text = str(raw_value)
    hashes = {digest(item) for item in candidate_strings(value_text) if item}
    matches = {name: target in hashes for name, target in targets.items()}
    for name, matched in matches.items():
        aggregate[name] = aggregate[name] or matched
    results.append({
        "key": key,
        "valueBytes": len(value_text.encode("utf-8")),
        "matchesImported": matches,
    })

print(json.dumps({
    "ok": True,
    "matchingSummary": aggregate,
    "candidateKeys": results,
}, ensure_ascii=False))

const url = "ws://127.0.0.1:19528/";
const socket = new WebSocket(url);
const messages: unknown[] = [];

function shape(value: unknown, depth = 0): unknown {
  if (depth > 4) return "[depth-limit]";
  if (Array.isArray(value)) {
    return {
      kind: "array",
      length: value.length,
      itemShapes: value.slice(0, 3).map((item) => shape(item, depth + 1)),
    };
  }
  if (value && typeof value === "object") {
    const source = value as Record<string, unknown>;
    const result: Record<string, unknown> = { kind: "object", keys: Object.keys(source).sort() };
    for (const [key, item] of Object.entries(source)) {
      if (key === "type" && typeof item === "string") result.type = item;
      else if (typeof item === "boolean" || typeof item === "number" || item === null) result[key] = item;
      else if (Array.isArray(item) || (item && typeof item === "object")) result[key] = shape(item, depth + 1);
      else if (typeof item === "string") result[key] = `[string:${item.length}]`;
    }
    return result;
  }
  return `[${typeof value}]`;
}

const done = new Promise<void>((resolve, reject) => {
  const timer = setTimeout(() => {
    socket.close();
    resolve();
  }, 4_000);

  const sendProbes = () => {
    const requests = [
      { type: "ping" },
      { type: "request.get_accounts" },
      { type: "request.get_current_account" },
      { type: "request.get_accounts", payload: {} },
      { type: "request.get_accounts", payload: { platform: "cursor" } },
      { type: "request.get_current_account", payload: { platform: "cursor" } },
      { id: "probe-accounts", type: "request.get_accounts", payload: { platform: "cursor" } },
      { requestId: "probe-current", type: "request.get_current_account", payload: { platform: "cursor" } },
    ];
    requests.forEach((request, index) => {
      setTimeout(() => socket.send(JSON.stringify(request)), 150 + index * 300);
    });
  };
  let probesSent = false;
  socket.addEventListener("message", (event) => {
    try {
      const parsed = JSON.parse(String(event.data));
      messages.push(shape(parsed));
      if (!probesSent && parsed?.type === "event.ready") {
        probesSent = true;
        sendProbes();
      }
    } catch {
      messages.push({ kind: "non-json", bytes: String(event.data).length });
    }
  });
  socket.addEventListener("error", () => {
    clearTimeout(timer);
    reject(new Error("Forge WebSocket probe failed"));
  });
  socket.addEventListener("close", () => {
    clearTimeout(timer);
    resolve();
  });
});

await done;
console.log(JSON.stringify({ ok: true, messageCount: messages.length, messages }));
